/**
 * CORRECAO - atendimento finalizado depois ficava com a data errada
 *
 * O PROBLEMA
 *
 * Ao finalizar hoje um atendimento que aconteceu ontem, o sistema gravava
 * tudo com a data de HOJE - nao com a data em que o atendimento realmente
 * aconteceu.
 *
 * Isso afetava, todos de uma vez:
 *   - a venda (entrava no faturamento do dia errado);
 *   - o procedimento na ficha da cliente;
 *   - a evolucao clinica;
 *   - a "ultima visita" da cliente (que alimenta os lembretes de retorno);
 *   - a data de conversao do lead.
 *
 * Ou seja: a ficha da cliente mostrava um procedimento em 02/09 quando ele
 * foi feito em 01/09, e o faturamento daquele dia ficava deslocado.
 *
 * A CORRECAO
 *
 * A data do atendimento passa a ser a data do AGENDAMENTO - quando ele de
 * fato aconteceu - em vez do momento em que alguem clicou em finalizar.
 *
 * IMPORTANTE - ISSO VALE DAQUI PARA FRENTE
 *
 * Atendimentos ja finalizados com a data errada nao sao corrigidos por
 * este script. Se algum caso especifico incomodar, da para ajustar na mao
 * pela tela de Vendas / ficha da cliente.
 *
 * Como usar: coloque este arquivo na RAIZ do projeto e rode
 *     node corrigir-data-do-atendimento.mjs
 *
 * E seguro rodar duas vezes.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { Buffer } from "node:buffer";

const ARQUIVO = "actions/agendamento.actions.ts";

console.log("\nCorrecao - data do atendimento finalizado\n");

if (!existsSync(ARQUIVO) || !existsSync("package.json")) {
  console.error("ERRO: rode este script na pasta raiz do projeto (a mesma do package.json).\n");
  process.exit(1);
}

