const usaCRLF = atual.includes("\r\n");
const novo = Buffer.from(CONTEUDO_B64, "base64").toString("utf8");
const saida = usaCRLF
  ? novo.replace(/\r\n/g, "\n").replace(/\n/g, "\r\n")
  : novo.replace(/\r\n/g, "\n");

if (atual === saida) {
  console.log("  [pulou] ja estava aplicada\n");
  process.exit(0);
}

writeFileSync(ARQUIVO, saida, "utf8");

